# Partition search for triples a+b=c
import itertools, json, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# generate candidate triples (a,b,c) with a<b and a+b=c in L
candidates = []
for a,b in itertools.combinations(L,2):
    s = a+b
    if s in L:
        candidates.append((a,b,s))
# backtracking to pick 15 disjoint triples covering all numbers
solution = []
used = set()

def backtrack(start):
    if len(solution)==15:
        if used==L:
            return True
        return False
    for i in range(start, len(candidates)):
        a,b,c = candidates[i]
        if a in used or b in used or c in used:
            continue
        solution.append((a,b,c))
        used.update([a,b,c])
        if backtrack(i+1):
            return True
        solution.pop()
        used.difference_update([a,b,c])
    return False

found = backtrack(0)
if found:
    # output partition
    print("Partition found:")
    for tri in solution:
        print(tri)
    witness = {"polarity":"positive","evidence":{"path":"execution://witness"},"data":{"partition":solution}}
else:
    print("No valid partition exists.")
    witness = {"polarity":"negative","evidence":{"path":"execution://witness"},"basis":"search","search_exhausted":true,"nodes_explored":null,"method":"backtrack"}
print("WITNESS: "+json.dumps(witness))

